import { StrictMode } from 'react'
import { createRoot } from 'react-dom/client'
import { BrowserRouter, Routes, Route } from 'react-router-dom'
import './index.css'
import { initializeI18n, LANGUAGE_STORAGE_KEY, supportedLanguages } from './i18n/config'
import App from './App.jsx'

// Show loading indicator while initializing
const root = createRoot(document.getElementById('root'));

// Minimal loading indicator
root.render(
  <div style={{
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    minHeight: '100vh',
    background: 'linear-gradient(135deg, #f0f9ff 0%, #e0f2fe 100%)'
  }}>
    <div style={{ textAlign: 'center' }}>
      <div style={{
        width: '40px',
        height: '40px',
        border: '4px solid #e0f2fe',
        borderTop: '4px solid #0ea5e9',
        borderRadius: '50%',
        animation: 'spin 1s linear infinite'
      }} />
      <style>{`@keyframes spin { 0% { transform: rotate(0deg); } 100% { transform: rotate(360deg); } }`}</style>
    </div>
  </div>
);

// Async initialization
(async () => {
  // Check if we were redirected from 404.html (GitHub Pages)
  const redirectPath = sessionStorage.getItem('redirectPath');
  const actualPath = redirectPath || window.location.pathname;

  // Detect language from the actual path (not the redirected one)
  const pathMatch = actualPath.match(/^\/([a-z]{2})(\/|$)/);
  let urlLang = null;

  if (pathMatch && supportedLanguages.includes(pathMatch[1])) {
    urlLang = pathMatch[1];
  }

  // Determine the language to use:
  // 1. URL language has ABSOLUTE priority (e.g., /ro means Romanian, period)
  // 2. For root page only: check localStorage, then browser language
  // 3. Default to English if nothing else
  let finalLang = 'en';

  if (urlLang) {
    // URL language takes absolute priority - no questions asked
    finalLang = urlLang;
  } else {
    // Only for root page: check localStorage first
    try {
      const stored = localStorage.getItem(LANGUAGE_STORAGE_KEY);
      if (stored && supportedLanguages.includes(stored)) {
        finalLang = stored;
      } else {
        // Then check browser language
        const browserLang = navigator.language || navigator.userLanguage;
        if (browserLang) {
          const langCode = browserLang.toLowerCase().split('-')[0];
          if (supportedLanguages.includes(langCode)) {
            finalLang = langCode;
          }
        }
      }
    } catch {
      // localStorage not available (incognito mode, etc.) - try browser language
      const browserLang = navigator.language || navigator.userLanguage;
      if (browserLang) {
        const langCode = browserLang.toLowerCase().split('-')[0];
        if (supportedLanguages.includes(langCode)) {
          finalLang = langCode;
        }
      }
    }
  }

  // If we were redirected, update the URL back to the intended path
  if (redirectPath) {
    window.history.replaceState(null, '', redirectPath);
    sessionStorage.removeItem('redirectPath');
  }

  // Initialize i18n with only the needed language
  await initializeI18n(finalLang);

  // Only use StrictMode in development - it causes double renders which slow down initial load
  const AppWrapper = import.meta.env.DEV ? (
    <StrictMode>
      <BrowserRouter>
        <Routes>
          <Route path="/:lang?" element={<App />} />
        </Routes>
      </BrowserRouter>
    </StrictMode>
  ) : (
    <BrowserRouter>
      <Routes>
        <Route path="/:lang?" element={<App />} />
      </Routes>
    </BrowserRouter>
  );

  root.render(AppWrapper);
})();
